insert into auth.users(id,aud,role,email) values('57000000-0000-4000-8000-000000000001','authenticated','authenticated','sync-owner@example.test'),('57000000-0000-4000-8000-000000000002','authenticated','authenticated','sync-other@example.test'),('57000000-0000-4000-8000-000000000003','authenticated','authenticated','sync-client@example.test');
