insert into public.bookings(id,workspace_id,client_record_id,starts_at,ends_at,status) values('97000000-0000-4000-8000-000000000001','67000000-0000-4000-8000-000000000001','77000000-0000-4000-8000-000000000001',now()+interval '10 days',now()+interval '10 days 1 hour','confirmed');
