insert into public.private_notes(id,workspace_id,workout_instance_id,text,author_user_id,device_id) values('f7000000-0000-4000-8000-000000000099','67000000-0000-4000-8000-000000000002','b7000000-0000-4000-8000-000000000002','Foreign secret','57000000-0000-4000-8000-000000000002','e7000000-0000-4000-8000-000000000002');
create function pg_temp.op(k text,e uuid,b integer,p jsonb,oid uuid default gen_random_uuid()) returns jsonb language sql as $$ select jsonb_build_object('operation_id',oid,'kind',k,'entity_id',e,'base_revision',b,'device_id','e7000000-0000-4000-8000-000000000001','payload',p,'created_at','2026-10-03T12:00:00Z') $$;
create function pg_temp.apply(o jsonb) returns jsonb language sql as $$ select public.apply_operations('67000000-0000-4000-8000-000000000001',jsonb_build_array(o))->'results'->0 $$;
select ok(not has_function_privilege('anon','public.apply_operations(uuid,jsonb)','EXECUTE'),'anonymous denied');
select ok(not has_table_privilege('authenticated','public.workout_sync_conflicts','INSERT'),'conflicts cannot be inserted directly');
select ok(not has_table_privilege('authenticated','public.workout_correction_drafts','UPDATE'),'drafts cannot be updated directly');
select set_config('request.jwt.claim.sub','57000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('test.create_op',pg_temp.op('create_workout','b7000000-0000-4000-8000-000000000001',0,'{"booking_id":"97000000-0000-4000-8000-000000000001"}')::text,true);
