select set_config('test.set_payload','{"workout_instance_id":"b7000000-0000-4000-8000-000000000001","workout_exercise_id":"c7000000-0000-4000-8000-000000000001","position":0,"reps":8,"seconds":null,"weight_g":40000}',true);
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000001',0,current_setting('test.set_payload')::jsonb))->>'status','applied','first set');
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000002',0,current_setting('test.set_payload')::jsonb))->>'status','applied','different set merges');
select is((select count(*)::integer from public.set_results where workout_instance_id='b7000000-0000-4000-8000-000000000001'),2,'both different IDs retained');
select is((select count(distinct position)::integer from public.set_results where workout_instance_id='b7000000-0000-4000-8000-000000000001'),2,'merged positions distinct');
select set_config('test.conflict',pg_temp.apply(jsonb_set(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000001',0,jsonb_set(current_setting('test.set_payload')::jsonb,'{reps}','9')),'{device_id}','"e7000000-0000-4000-8000-000000000002"'))::text,true);
select is(current_setting('test.conflict')::jsonb->>'status','conflict','same stale ID conflicts');
select is((select reps from public.set_results where id='d7000000-0000-4000-8000-000000000001'),8,'current set preserved');
select is((select incoming_operation->'payload'->>'reps' from public.workout_sync_conflicts where id=(current_setting('test.conflict')::jsonb->>'conflict_id')::uuid),'9','incoming set preserved');
select is((select current_version->>'device_id' from public.workout_sync_conflicts where id=(current_setting('test.conflict')::jsonb->>'conflict_id')::uuid),'e7000000-0000-4000-8000-000000000001','current device retained');
select is((select incoming_operation->>'device_id' from public.workout_sync_conflicts where id=(current_setting('test.conflict')::jsonb->>'conflict_id')::uuid),'e7000000-0000-4000-8000-000000000002','incoming device retained');
select is(pg_temp.apply(pg_temp.op('resolve_conflict','d7000000-0000-4000-8000-000000000001',1,jsonb_build_object('conflict_id',current_setting('test.conflict')::jsonb->>'conflict_id','selected_version',null,'expected_revision',1)))->>'error_code','invalid_payload','null selected version cannot implicitly choose current');
select is(pg_temp.apply(pg_temp.op('resolve_conflict','d7000000-0000-4000-8000-000000000001',1,jsonb_build_object('conflict_id',current_setting('test.conflict')::jsonb->>'conflict_id','selected_version','current','expected_revision',null)))->>'error_code','invalid_payload','null expected revision rejected');
select is(pg_temp.apply(pg_temp.op('resolve_conflict','d7000000-0000-4000-8000-000000000001',1,jsonb_build_object('conflict_id',current_setting('test.conflict')::jsonb->>'conflict_id','selected_version','incoming','expected_revision',1)))->>'status','applied','explicit incoming resolution');
select is((select reps from public.set_results where id='d7000000-0000-4000-8000-000000000001'),9,'selected incoming committed');
select is(pg_temp.apply(pg_temp.op('delete_set','d7000000-0000-4000-8000-000000000001',2,current_setting('test.set_payload')::jsonb - array['position','reps','seconds','weight_g']))->>'status','applied','delete creates tombstone');
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000001',2,current_setting('test.set_payload')::jsonb))->>'status','conflict','edit against tombstone conflicts');
select is(pg_temp.apply(pg_temp.op('set_note','f7000000-0000-4000-8000-000000000001',0,'{"workout_instance_id":"b7000000-0000-4000-8000-000000000001","text":"Shared text","shared":true}'))->>'status','applied','shared note');
select is(pg_temp.apply(pg_temp.op('set_note','f7000000-0000-4000-8000-000000000001',0,'{"workout_instance_id":"b7000000-0000-4000-8000-000000000001","text":"Private incoming","shared":false}'))->>'status','conflict','visibility conflict');
select is((select count(*)::integer from public.session_notes where id='f7000000-0000-4000-8000-000000000001'),0,'visibility conflict closes shared exposure');
select is((select text from public.private_notes where id='f7000000-0000-4000-8000-000000000001'),'Shared text','closed current text retained privately');
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000099',5,current_setting('test.set_payload')::jsonb))->>'error_code','entity_unavailable','missing set cannot claim existing revision');
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000098',0,jsonb_set(current_setting('test.set_payload')::jsonb,'{workout_exercise_id}','"c7000000-0000-4000-8000-000000000099"')))->>'error_code','invalid_payload','missing parent rejected');
select set_config('test.stale_conflict',pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000002',0,current_setting('test.set_payload')::jsonb))::text,true);
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000002',1,jsonb_set(current_setting('test.set_payload')::jsonb,'{reps}','12')))->>'status','applied','target changes while conflict unresolved');
select is(pg_temp.apply(pg_temp.op('resolve_conflict','d7000000-0000-4000-8000-000000000002',1,jsonb_build_object('conflict_id',current_setting('test.stale_conflict')::jsonb->>'conflict_id','selected_version','incoming','expected_revision',1)))->>'error_code','stale_conflict','resolution checks actual target revision');
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000097',0,current_setting('test.set_payload')::jsonb))->>'error_code','entity_unavailable','foreign global set ID cannot overwrite');
select is(pg_temp.apply(pg_temp.op('set_note','f7000000-0000-4000-8000-000000000099',0,'{"workout_instance_id":"b7000000-0000-4000-8000-000000000001","text":"overwrite","shared":true}'))->>'error_code','entity_unavailable','foreign global note ID cannot migrate or overwrite');
select is(pg_temp.apply(pg_temp.op('replace_exercise','c7000000-0000-4000-8000-000000000010',0,jsonb_build_object('workout_instance_id','b7000000-0000-4000-8000-000000000001','replaced_from_id','c7000000-0000-4000-8000-000000000001','exercise_id',current_setting('test.exercise_id'),'position',0,'planned_sets',3)))->>'status','conflict','append delivered before replacement conflicts');
select is((select reps from public.set_results where id='d7000000-0000-4000-8000-000000000002'),12,'append-before-replacement original set preserved');
select is(pg_temp.apply(pg_temp.op('add_exercise','c7000000-0000-4000-8000-000000000020',0,jsonb_build_object('workout_instance_id','b7000000-0000-4000-8000-000000000001','exercise_id',current_setting('test.exercise_id'),'position',20,'planned_sets',3)))->>'status','applied','second structure fixture');
select is(pg_temp.apply(pg_temp.op('replace_exercise','c7000000-0000-4000-8000-000000000021',0,jsonb_build_object('workout_instance_id','b7000000-0000-4000-8000-000000000001','replaced_from_id','c7000000-0000-4000-8000-000000000020','exercise_id',current_setting('test.exercise_id'),'position',20,'planned_sets',3)))->>'status','applied','replacement delivered first');
select set_config('test.structure_conflict',pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000020',0,jsonb_set(current_setting('test.set_payload')::jsonb,'{workout_exercise_id}','"c7000000-0000-4000-8000-000000000020"')))::text,true);
select is(current_setting('test.structure_conflict')::jsonb->>'status','conflict','replacement-before-append conflicts');
select is((select incoming_operation->'payload'->>'workout_exercise_id' from public.workout_sync_conflicts where id=(current_setting('test.structure_conflict')::jsonb->>'conflict_id')::uuid),'c7000000-0000-4000-8000-000000000020','incoming append retains original exercise identity');
select is(pg_temp.apply(pg_temp.op('resolve_conflict','d7000000-0000-4000-8000-000000000020',2,jsonb_build_object('conflict_id',current_setting('test.structure_conflict')::jsonb->>'conflict_id','selected_version','incoming','expected_revision',2)))->>'status','applied','structural incoming version resolves');
select is((select workout_exercise_id::text from public.set_results where id='d7000000-0000-4000-8000-000000000020'),'c7000000-0000-4000-8000-000000000020','selected append never moves into replacement');
select is(pg_temp.apply(pg_temp.op('finish_workout','b7000000-0000-4000-8000-000000000001',1,'{}'))->>'status','applied','finish');
select is(pg_temp.apply(pg_temp.op('upsert_set','d7000000-0000-4000-8000-000000000002',1,current_setting('test.set_payload')::jsonb))->>'status','correction_draft','finished edit preserved as draft');
select is((select revision from public.set_results where id='d7000000-0000-4000-8000-000000000002'),2,'finished set immutable');
select is((public.apply_operations('67000000-0000-4000-8000-000000000001',jsonb_build_array(pg_temp.op('unknown','b7000000-0000-4000-8000-000000000001',0,'{}'),pg_temp.op('set_note','f7000000-0000-4000-8000-000000000002',0,'{"workout_instance_id":"b7000000-0000-4000-8000-000000000001","text":"draft","shared":false}')))->'results'->1->>'status'),'correction_draft','bad operation does not block next operation');
select set_config('request.jwt.claim.sub','57000000-0000-4000-8000-000000000003',true);
select is((select count(*)::integer from public.workout_instances),1,'linked client sees completed own workout');
select is((select count(*)::integer from public.private_notes),0,'linked client cannot read private notes');
select is((select count(*)::integer from public.sync_operations),0,'linked client cannot read receipts');
select is((select count(*)::integer from public.workout_sync_conflicts),0,'linked client cannot read conflict versions');
select is((select count(*)::integer from public.workout_correction_drafts),0,'linked client cannot read correction drafts');
select throws_ok($$select public.apply_operations('67000000-0000-4000-8000-000000000001','[]')$$,'42501','Workspace unavailable','linked client cannot write results');
select set_config('request.jwt.claim.sub','57000000-0000-4000-8000-000000000002',true);
select is((select count(*)::integer from public.workout_sync_conflicts),0,'foreign owner cannot read conflicts');
select is((select count(*)::integer from public.workout_correction_drafts),0,'foreign owner cannot read drafts');
select is((select count(*)::integer from public.sync_operations),0,'foreign owner cannot read receipts');
select is((select reps from public.set_results where id='d7000000-0000-4000-8000-000000000097'),77,'foreign set unchanged after collision');
select is((select text from public.private_notes where id='f7000000-0000-4000-8000-000000000099'),'Foreign secret','foreign note unchanged after collision');
select throws_ok($$select public.apply_operations('67000000-0000-4000-8000-000000000001','[]')$$,'42501','Workspace unavailable','foreign owner cannot apply');
reset role;
select * from finish();
rollback;
